clinic_dashboard_mv.definition:
select "clinics"."id", "clinics"."name", (
    SELECT COUNT(*) FROM "appointment" WHERE "appointment"."clinic_id" = "clinics"."id"
  ) as "totalAppointments", (
    SELECT COUNT(*) FROM "appointment"
    WHERE date("appointment"."appointment_date"/1000, 'unixepoch') = date('now') AND "appointment"."clinic_id" = "clinics"."id"
  ) as "todayAppointments", (
    SELECT COUNT(*) FROM "appointment"
    WHERE date("appointment"."appointment_date"/1000, 'unixepoch') > date('now') AND "appointment"."status" IN ('SCHEDULED', 'PENDING') AND "appointment"."clinic_id" = "clinics"."id"
  ) as "upcomingAppointments", (
    SELECT COUNT(*) FROM "appointment"
    WHERE "appointment"."status" = 'COMPLETED' AND "appointment"."clinic_id" = "clinics"."id"
  ) as "completedAppointments", (
    SELECT COUNT(*) FROM "patient" WHERE "patient"."clinic_id" = "clinics"."id"
  ) as "totalPatients", (
    SELECT COUNT(*) FROM "patient"
    WHERE "patient"."is_active" = true AND "patient"."clinic_id" = "clinics"."id"
  ) as "activePatients", (
    SELECT COUNT(*) FROM "patient"
    WHERE date("patient"."created_at"/1000, 'unixepoch') >= strftime('%Y-%m-01', 'now') AND "patient"."clinic_id" = "clinics"."id"
  ) as "newPatientsThisMonth", (
        SELECT 0
      ) as "avgWaitingTime", (
    SELECT COALESCE(SUM("payment"."total_amount"), 0) FROM "payment"
    WHERE date("payment"."payment_date"/1000, 'unixepoch') >= strftime('%Y-%m-01', 'now') AND "payment"."clinic_id" = "clinics"."id"
  ) as "monthlyRevenue", (
    SELECT COALESCE(SUM("payment"."total_amount"), 0) FROM "payment"
    WHERE "payment"."clinic_id" = "clinics"."id"
  ) as "totalRevenue", (SELECT COUNT(*) FROM "doctor" WHERE "doctor"."clinic_id" = "clinics"."id" AND "doctor"."is_active" = true AND "doctor"."status" = 'ACTIVE') as "activeDoctors", (SELECT AVG("doctor"."rating") FROM "doctor" WHERE "doctor"."clinic_id" = "clinics"."id") as "averageDoctorRating", (SELECT COUNT(*) FROM "immunization" WHERE "immunization"."clinic_id" = "clinics"."id" AND "immunization"."date" <= unixepoch('now', '+7 days') * 1000) as "immunizationsDue", (SELECT COUNT(*) FROM "vital_sign" WHERE "vital_sign"."clinic_id" = "clinics"."id" AND "vital_sign"."recorded_at" < unixepoch('now', '-3 months') * 1000) as "growthChecksPending", (SELECT COUNT(*) FROM "staff" WHERE "staff"."clinic_id" = "clinics"."id") as "totalStaff", (unixepoch() * 1000) as "updatedAt" from "clinics" left join "patient" on "patient"."clinic_id" = "clinics"."id" left join "appointment" on "appointment"."clinic_id" = "clinics"."id" left join "doctor" on "doctor"."clinic_id" = "clinics"."id" left join "payment" on "payment"."clinic_id" = "clinics"."id" left join "immunization" on "immunization"."clinic_id" = "clinics"."id" left join "vital_sign" on "vital_sign"."clinic_id" = "clinics"."id" left join "staff" on "staff"."clinic_id" = "clinics"."id" group by "clinics"."id", "clinics"."name"
